BEGIN;
CREATE TABLE pg14_sandbox_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,environment text NOT NULL CHECK(environment='sandbox'),scenario text NOT NULL,creation_key text NOT NULL,intent_id uuid NOT NULL,observation_id uuid NOT NULL,actor_id uuid NOT NULL,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,creation_key),FOREIGN KEY(workspace_id,environment,intent_id) REFERENCES payment_intents(workspace_id,environment,id));
ALTER TABLE pg14_sandbox_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE pg14_sandbox_runs FORCE ROW LEVEL SECURITY;CREATE POLICY pg14_runs_owner ON pg14_sandbox_runs TO CURRENT_USER USING(true) WITH CHECK(true);REVOKE ALL ON pg14_sandbox_runs FROM PUBLIC,ekmivo_finance_reader,ekmivo_financial_worker;
CREATE FUNCTION pg14_run(w uuid,a uuid,scenario_name text,k text,payer text,evidence bytea) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE account uuid;observed_account uuid;inbound uuid;observation uuid;intent uuid;run pg14_sandbox_runs;at_time timestamptz;BEGIN
 IF (SELECT environment FROM financial_realm WHERE singleton)<>'sandbox' THEN RAISE EXCEPTION 'sandbox realm required' USING ERRCODE='42501';END IF;PERFORM pg06_scope(w,'sandbox');
 IF a IS NULL OR payer!~'^[a-f0-9]{64}$' OR octet_length(evidence)<29 OR length(k) NOT BETWEEN 16 AND 128 OR scenario_name NOT IN('exact-unique','wrong-payer','under-amount','over-amount','before-window','after-window','missing-time','outgoing','missing-payer','missing-amount','unknown-direction','wrong-account','wrong-method') THEN RAISE EXCEPTION 'unsupported scenario' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('pg14:'||w::text,0));SELECT * INTO run FROM pg14_sandbox_runs WHERE workspace_id=w AND creation_key=k;IF FOUND THEN IF run.scenario<>scenario_name THEN RAISE EXCEPTION 'scenario key conflict' USING ERRCODE='23505';END IF;RETURN to_jsonb(run)||jsonb_build_object('simulation',true);END IF;
 IF(SELECT count(*) FROM pg14_sandbox_runs WHERE workspace_id=w AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'sandbox scenario limit' USING ERRCODE='23514';END IF;
 INSERT INTO financial_receiving_accounts(workspace_id,environment,method,identity_hmac,display_suffix) VALUES(w,'sandbox','bkash',encode(digest('fixture:'||w::text||k,'sha256'),'hex'),'0000') RETURNING id INTO account;
 INSERT INTO payment_intents(workspace_id,environment,merchant_reference,amount_minor,expires_at) VALUES(w,'sandbox','SIMULATION-'||substr(encode(digest(k,'sha256'),'hex'),1,24),5500,now()+interval '30 minutes') RETURNING id INTO intent;
 INSERT INTO payment_attempts(workspace_id,environment,intent_id,receiving_account_id,payer_hmac,payer_suffix,amount_minor,method,window_start,window_end,policy_version,issued_at) VALUES(w,'sandbox',intent,account,payer,'0000',5500,'bkash',CASE WHEN scenario_name='after-window' THEN now()-interval '10 minutes' ELSE now()-interval '1 minute' END,CASE WHEN scenario_name='after-window' THEN now()-interval '5 minutes' ELSE now()+interval '15 minutes' END,1,CASE WHEN scenario_name='after-window' THEN now()-interval '10 minutes' ELSE now()-interval '1 minute' END);
 observed_account:=account;IF scenario_name='wrong-account' THEN INSERT INTO financial_receiving_accounts(workspace_id,environment,method,identity_hmac,display_suffix) VALUES(w,'sandbox','bkash',encode(digest('different:'||w::text||k,'sha256'),'hex'),'1111') RETURNING id INTO observed_account;END IF;
 at_time:=CASE scenario_name WHEN 'before-window' THEN now()-interval '5 minutes' WHEN 'after-window' THEN now()+interval '4 minutes' WHEN 'missing-time' THEN NULL ELSE now() END;
 -- after-window uses an already-ended immutable attempt window.
 IF scenario_name='after-window' THEN at_time:=now()-interval '1 second';END IF;
 INSERT INTO financial_inbound_events(workspace_id,environment,source_kind,source_event_id,event_digest,original_source_at,encrypted_evidence) VALUES(w,'sandbox','sandbox_fixture','simulation:'||intent::text,encode(digest(k,'sha256'),'hex'),at_time,evidence) RETURNING id INTO inbound;
 INSERT INTO financial_receipt_observations(workspace_id,environment,inbound_event_id,receiving_account_id,provider_reference_hmac,payer_hmac,amount_minor,method,direction,original_transaction_at,time_precision,parser_version) VALUES(w,'sandbox',inbound,observed_account,encode(digest('ref:'||k,'sha256'),'hex'),CASE WHEN scenario_name='wrong-payer' THEN encode(digest(payer,'sha256'),'hex') WHEN scenario_name='missing-payer' THEN NULL ELSE payer END,CASE scenario_name WHEN 'under-amount' THEN 5000 WHEN 'over-amount' THEN 6000 WHEN 'missing-amount' THEN NULL ELSE 5500 END,CASE WHEN scenario_name='wrong-method' THEN 'nagad' ELSE 'bkash' END,CASE WHEN scenario_name='outgoing' THEN 'outgoing' WHEN scenario_name='unknown-direction' THEN 'unknown' ELSE 'incoming' END,at_time,CASE WHEN at_time IS NULL THEN 'unknown' ELSE 'second' END,1) RETURNING id INTO observation;
 INSERT INTO pg07_receipt_results(workspace_id,environment,observation_id) VALUES(w,'sandbox',observation);
 INSERT INTO pg14_sandbox_runs(workspace_id,environment,scenario,creation_key,intent_id,observation_id,actor_id) VALUES(w,'sandbox',scenario_name,k,intent,observation,a) RETURNING * INTO run;
 INSERT INTO pg09_audit(workspace_id,environment,actor_id,resource,resource_id,action) VALUES(w,'sandbox',a,'sandbox',run.id,'simulate');RETURN to_jsonb(run)||jsonb_build_object('simulation',true);
END $$;
CREATE FUNCTION pg14_runs(w uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM pg06_scope(w,'sandbox');RETURN coalesce((SELECT jsonb_agg(to_jsonb(r)||jsonb_build_object('simulation',true,'state',pg05_intent_state(w,'sandbox',r.intent_id),'match_status',m.status,'reason',m.reason)) FROM pg14_sandbox_runs r JOIN pg07_receipt_results m ON m.observation_id=r.observation_id WHERE r.workspace_id=w AND r.archived_at IS NULL),'[]');END $$;
CREATE FUNCTION pg14_reset(w uuid,a uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r pg14_sandbox_runs;n bigint:=0;BEGIN PERFORM pg06_scope(w,'sandbox');IF(SELECT environment FROM financial_realm WHERE singleton)<>'sandbox' THEN RAISE EXCEPTION 'sandbox only' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('pg14:'||w::text,0));FOR r IN SELECT * FROM pg14_sandbox_runs WHERE workspace_id=w AND archived_at IS NULL LOOP IF pg05_intent_state(w,'sandbox',r.intent_id) NOT IN('completed','cancelled','expired') THEN PERFORM pg05_cancel_intent(w,'sandbox',r.intent_id);END IF;UPDATE pg14_sandbox_runs SET archived_at=now() WHERE id=r.id;n:=n+1;END LOOP;INSERT INTO pg09_audit(workspace_id,environment,actor_id,resource,action) VALUES(w,'sandbox',a,'sandbox','archive-reset');RETURN n;END $$;
REVOKE ALL ON FUNCTION pg14_run(uuid,uuid,text,text,text,bytea),pg14_runs(uuid),pg14_reset(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION pg14_run(uuid,uuid,text,text,text,bytea),pg14_runs(uuid),pg14_reset(uuid,uuid) TO ekmivo_finance_reader;
COMMIT;
